import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync,readdirSync,lstatSync}from'node:fs';import{join,resolve}from'node:path';import{spawnSync}from'node:child_process';import{createHash}from'node:crypto';
import ts from 'typescript';
const root=process.cwd(),dir=resolve('.loomake/quality/run-scale-probes'),hash=p=>createHash('sha256').update(readFileSync(p)).digest('hex');
for(const[name,source]of [['project','packages/kit/test/project.ts'],['helpers','packages/runner/test/helpers.ts']]){let text=ts.transpileModule(readFileSync(source,'utf8'),{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext}}).outputText;text=text.replace('../../kit/test/project.js','./project.mjs');writeFileSync(join(dir,`${name}.mjs`),text);}
const{makeRepo,CHANGE}=await import('./helpers.mjs');
function disk(base){let files=0,logicalBytes=0,allocatedBytes=0;const seen=new Set();function visit(p){const s=lstatSync(p);const id=`${s.dev}:${s.ino}`;if(seen.has(id))return;seen.add(id);allocatedBytes+=s.blocks*512;if(s.isDirectory()){for(const n of readdirSync(p))visit(join(p,n));}else{files++;logicalBytes+=s.size;}}visit(base);return{files,logicalBytes,allocatedBytes};}
const control=spawnSync(process.execPath,['-e',`const n=require('node:net').connect({host:'127.0.0.1',port:9});n.on('error',e=>{console.log(e.code);process.exit(e.code==='EPERM'?0:1)});n.on('connect',()=>process.exit(1));`],{encoding:'utf8',timeout:5000});assert.equal(control.status,0,control.stdout+control.stderr);assert.equal(control.stdout.trim(),'EPERM');
const result={sourceCommit:spawnSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).stdout.trim(),platform:process.platform,arch:process.arch,node:process.version,networkControl:'EPERM',scope:'Compiled CLI, real local Git including push to local bare origin, fixture engine/gh. One requirement and synthetic quality report per run; varying tasks only. Preparation excluded. Sampled process-tree RSS, not exact high-water mark. st_blocks allocation, not exclusive physical storage.',inputs:Object.fromEntries(['packages/kit/test/project.ts','packages/runner/test/helpers.ts','scripts/deny-network.py',...['monitor.py','run-scale.mjs','project.mjs','helpers.mjs'].map(f=>`.loomake/quality/run-scale-probes/${f}`)].map(f=>[f,hash(f)])),runs:[]};
for(const count of [1,10,50])for(let repeat=1;repeat<=3;repeat++){
 const tasks=['## 1. 実装',...Array.from({length:count},(_,i)=>`- [ ] 1.${i+1} タスク${i+1}（REQ-012）`),'','## 2. 確認','- [ ] 2.1 完了ゲート <!-- loomake:gate=done -->',''].join('\n');const repo=makeRepo({tasks,run:{timeoutMinutes:2}});let row;
 try{repo.plan(Array.from({length:count},(_,i)=>({write:{'impl.txt':`task ${i+1}\n`}})));const before=disk(repo.base),initial=Number(repo.git('rev-list','--count','HEAD'));const output=join(dir,`n${count}-r${repeat}`);const proc=spawnSync('python3',[join(dir,'monitor.py'),output,process.execPath,join(root,'packages/cli/dist/cli.js'),'run','--change',CHANGE],{cwd:repo.root,env:repo.env,encoding:'utf8',timeout:180000,maxBuffer:1024*1024});const measurement=JSON.parse(readFileSync(join(output,'measurement.json'),'utf8'));assert.equal(proc.status,0,readFileSync(join(output,'stdout'),'utf8')+readFileSync(join(output,'stderr'),'utf8'));
 const runs=join(repo.root,'.loomake/runs');const summary=JSON.parse(readFileSync(join(runs,readdirSync(runs).filter(x=>x!=='.gitignore').sort().at(-1),'summary.json'),'utf8'));assert.equal(summary.status,'completed');assert.deepEqual(summary.remainingTasks,[]);assert.equal(repo.calls().length,count);assert.equal(repo.prs().length,1);assert.equal(readFileSync(join(repo.root,'impl.txt'),'utf8'),`task ${count}\n`);assert(!readFileSync(join(repo.root,`openspec/changes/${CHANGE}/tasks.md`),'utf8').includes('- [ ]'));const commits=Number(repo.git('rev-list','--count','HEAD'))-initial;assert.equal(commits,count+2);assert.equal(repo.git('status','--porcelain'),'');const after=disk(repo.base);row={count,repeat,...measurement,before,after,growth:{logicalBytes:after.logicalBytes-before.logicalBytes,allocatedBytes:after.allocatedBytes-before.allocatedBytes},commits,engineCalls:repo.calls().length,fakePrs:repo.prs().length,summaryStatus:summary.status,outputBytes:readFileSync(join(output,'stdout')).length+readFileSync(join(output,'stderr')).length,stdoutSha256:hash(join(output,'stdout')),stderrSha256:hash(join(output,'stderr'))};
 }finally{repo.cleanup();}
 result.runs.push(row);writeFileSync(join(dir,'results.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(row));
}

